CustomField.formula:
IF( OR /*If Start Date is in current Financial Year. (Start Date should be after June of Current Year and before (or on) June of next year.) */ ( AND /*Start Date is next year before June.*/ ( MONTH(Start_Date__c) <= 6, YEAR(Start_Date__c) = (YEAR( TODAY())+1) ), AND /*Start Date is current year after June.*/ ( MONTH(Start_Date__c) > 6, YEAR(Start_Date__c) = YEAR( TODAY()) ) ),
IF( MONTH( Start_Date__c ) > 6, /*After June*/ (3*VALUE( TEXT( Ramp_up_factor__c ))/100 *( Amount /12)) + ( ((19-MONTH( Start_Date__c))-3) *(Amount /12) ) , IF( OR /*Start Date Month <= March*/ ( MONTH( Start_Date__c ) < 3, MONTH( Start_Date__c ) = 3 ) , (3*VALUE( TEXT( Ramp_up_factor__c ))/100 *( Amount /12)) + ( ((7-MONTH( Start_Date__c))-3) *(Amount /12) ), (VALUE( TEXT( Ramp_up_factor__c ))/100) /*Ramp_up_factor__c will not be multiplied by 3 as 3 or less months are left in Financial Year*/ *(7-MONTH( Start_Date__c )) *(Amount /12)
) ), 0 )
